import {
  useCallback,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
} from 'react'
import { Button, Checkbox } from '@shared'

/* Relative to this page (/ai-label-prototype/), in dev and in the build. */
const PROTOTYPE_URL = './prototype/index.html'
const DEVICE_WIDTH = 390
const DEVICE_HEIGHT = 844
const PAGE_BOTTOM_PADDING = 32
const PAGE_SIDE_PADDING = 16
const MIN_SCALE = 0.3

/* Content that the footer banner of a screen can say is generated by AI. */
const AI_CONTENT = [
  { id: 'images', label: 'Images' },
  { id: 'descriptions', label: 'Descriptions' },
  { id: 'dietary tags', label: 'Dietary tags' },
  { id: 'translations', label: 'Translations' },
] as const

/* Each screen offers its own subset: the Product view has no images option. */
const AI_CONTENT_SCREENS = [
  {
    id: 'store-view',
    label: 'Store view',
    options: AI_CONTENT.map((item) => item.id) as string[],
  },
  {
    id: 'product-view',
    label: 'Product view',
    options: ['descriptions', 'dietary tags', 'translations'],
  },
] as const

type AiContentScreen = (typeof AI_CONTENT_SCREENS)[number]['id']
type AiContentState = Record<AiContentScreen, string[]>

type ContentDropdownProps = {
  label: string
  options: readonly string[]
  value: string[]
  onChange: (value: string[]) => void
}

function ContentDropdown({
  label,
  options,
  value,
  onChange,
}: ContentDropdownProps) {
  const [open, setOpen] = useState(false)
  const ref = useRef<HTMLDivElement>(null)

  useEffect(() => {
    if (!open) return
    const onPointerDown = (event: PointerEvent) => {
      if (!ref.current?.contains(event.target as Node)) setOpen(false)
    }
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') setOpen(false)
    }
    document.addEventListener('pointerdown', onPointerDown)
    document.addEventListener('keydown', onKeyDown)
    return () => {
      document.removeEventListener('pointerdown', onPointerDown)
      document.removeEventListener('keydown', onKeyDown)
    }
  }, [open])

  const toggle = (id: string) => {
    // Keep the canonical order so the banner copy is stable.
    onChange(
      options.filter((itemId) =>
        itemId === id ? !value.includes(id) : value.includes(itemId),
      ),
    )
  }

  const summary =
    value.length === options.length
      ? 'All'
      : value.length === 0
        ? 'None'
        : `${value.length} of ${options.length}`

  return (
    <div className="dropdown" ref={ref}>
      <button
        type="button"
        className="dropdown__button"
        aria-haspopup="true"
        aria-expanded={open}
        onClick={() => setOpen((current) => !current)}
      >
        <span>
          {label} AI content: <strong>{summary}</strong>
        </span>
        <span aria-hidden="true">{open ? '▴' : '▾'}</span>
      </button>
      {open && (
        <div
          className="dropdown__panel"
          role="group"
          aria-label={`Content generated by AI in the ${label}`}
        >
          {AI_CONTENT.filter((item) => options.includes(item.id)).map(
            (item) => (
              <label key={item.id} className="dropdown__option">
                <input
                  type="checkbox"
                  checked={value.includes(item.id)}
                  onChange={() => toggle(item.id)}
                />
                {item.label}
              </label>
            ),
          )}
        </div>
      )}
    </div>
  )
}

type AiLabelState = {
  total: number
  index: number
  screen: string | null
  name: string | null
}

export default function App() {
  const [highlightAi, setHighlightAi] = useState(false)
  const [referenceImage, setReferenceImage] = useState(false)
  const [aiContent, setAiContent] = useState<AiContentState>({
    'store-view': [...AI_CONTENT_SCREENS[0].options],
    'product-view': [...AI_CONTENT_SCREENS[1].options],
  })
  const [aiLabel, setAiLabel] = useState<AiLabelState>({
    total: 0,
    index: -1,
    screen: null,
    name: null,
  })
  const frameRef = useRef<HTMLIFrameElement>(null)
  const sideRef = useRef<HTMLElement>(null)
  const slotRef = useRef<HTMLDivElement>(null)
  const [scale, setScale] = useState(1)

  /* Fit the device into the viewport height: scale it down, never up. */
  useLayoutEffect(() => {
    const update = () => {
      const slot = slotRef.current
      if (!slot) return
      const availableHeight =
        window.innerHeight -
        slot.getBoundingClientRect().top -
        PAGE_BOTTOM_PADDING
      const availableWidth = window.innerWidth - PAGE_SIDE_PADDING * 2
      const fit = Math.min(
        availableHeight / DEVICE_HEIGHT,
        availableWidth / DEVICE_WIDTH,
      )
      setScale(Math.min(1, Math.max(MIN_SCALE, fit)))
    }
    update()
    window.addEventListener('resize', update)
    const observer = new ResizeObserver(update)
    if (sideRef.current) observer.observe(sideRef.current)
    return () => {
      window.removeEventListener('resize', update)
      observer.disconnect()
    }
  }, [])

  const post = useCallback((message: Record<string, unknown>) => {
    frameRef.current?.contentWindow?.postMessage(
      message,
      window.location.origin,
    )
  }, [])

  useEffect(() => {
    post({ type: 'highlight-ai', value: highlightAi })
  }, [highlightAi, post])

  useEffect(() => {
    post({ type: 'reference-image', value: referenceImage })
  }, [referenceImage, post])

  useEffect(() => {
    AI_CONTENT_SCREENS.forEach(({ id }) => {
      post({ type: 'ai-content', screen: id, value: aiContent[id] })
    })
  }, [aiContent, post])

  useEffect(() => {
    const onMessage = (event: MessageEvent) => {
      if (
        event.origin !== window.location.origin ||
        event.source !== frameRef.current?.contentWindow ||
        event.data?.type !== 'ai-labels'
      ) {
        return
      }
      const { total, index, screen, name } = event.data
      setAiLabel({ total, index, screen, name })
    }
    window.addEventListener('message', onMessage)
    return () => window.removeEventListener('message', onMessage)
  }, [])

  const step = (direction: 1 | -1) => {
    if (aiLabel.total === 0) return
    const from =
      aiLabel.index < 0 && direction === -1 ? aiLabel.total : aiLabel.index
    post({ type: 'focus-ai-label', index: from + direction })
  }

  return (
    <main className="page">
      <aside className="page__side" ref={sideRef}>
        <header className="page__header">
          <h1 className="page__title">AI labels touchpoints</h1>
        </header>
        <Checkbox
          label="Highlight AI labels"
          checked={highlightAi}
          onChange={(event) => {
              setHighlightAi(event.target.checked)
              if (event.target.checked) {
                post({ type: 'focus-ai-label', index: 0 })
              }
            }}
        />
        <Checkbox
          label="Reference image"
          checked={referenceImage}
          onChange={(event) => setReferenceImage(event.target.checked)}
        />
        {AI_CONTENT_SCREENS.map(({ id, label, options }) => (
          <ContentDropdown
            key={id}
            label={label}
            options={options}
            value={aiContent[id]}
            onChange={(value) =>
              setAiContent((current) => ({ ...current, [id]: value }))
            }
          />
        ))}
        {highlightAi && (
          <>
            <div className="label-nav" role="group" aria-label="AI labels">
              <Button
                variant="icon"
                aria-label="Previous AI label"
                disabled={aiLabel.total === 0}
                onClick={() => step(-1)}
              >
                &larr;
              </Button>
              <span className="label-nav__count" aria-live="polite">
                {aiLabel.index + 1 > 0 ? aiLabel.index + 1 : '–'} /{' '}
                {aiLabel.total}
              </span>
              <Button
                variant="icon"
                aria-label="Next AI label"
                disabled={aiLabel.total === 0}
                onClick={() => step(1)}
              >
                &rarr;
              </Button>
            </div>
            {aiLabel.name && (
              <p className="label-nav__name">
                {aiLabel.name}
                <span>{aiLabel.screen}</span>
              </p>
            )}
          </>
        )}
      </aside>
      <div
        className="device-slot"
        ref={slotRef}
        style={{ width: DEVICE_WIDTH * scale, height: DEVICE_HEIGHT * scale }}
      >
        <div className="device" style={{ transform: `scale(${scale})` }}>
          <iframe
            ref={frameRef}
            className="device__screen"
            src={PROTOTYPE_URL}
            title="Store flow prototype"
            onLoad={() => {
              post({ type: 'highlight-ai', value: highlightAi })
              post({ type: 'reference-image', value: referenceImage })
              AI_CONTENT_SCREENS.forEach(({ id }) => {
                post({ type: 'ai-content', screen: id, value: aiContent[id] })
              })
              post({ type: 'ai-labels-query' })
            }}
          />
        </div>
      </div>
    </main>
  )
}
